<div class="space-y-6"><div class="page-heading"><div><p class="eyebrow">Finance / Quotes</p><div class="flex items-center gap-3"><h1>{{ $quote->quote_number }}</h1><span class="status-badge">{{ $quote->status->label() }}</span></div><p>{{ $quote->lead?->customer_name }} · Revision {{ $quote->revision }}</p></div><div class="flex flex-wrap gap-2">@if($quote->status===\App\Enums\QuoteStatus::Draft)<button wire:click="transition('sent')" wire:confirm="Mark this quote as sent?" class="btn-primary">Mark sent</button>@elseif($quote->status===\App\Enums\QuoteStatus::Sent)<button wire:click="transition('accepted')" class="btn-primary">Accept</button><button wire:click="transition('rejected')" class="btn-secondary">Reject</button><button wire:click="transition('expired')" class="btn-secondary">Expire</button>@elseif($quote->status===\App\Enums\QuoteStatus::Accepted)<button wire:click="convert" wire:confirm="Create an invoice from this accepted quote?" class="btn-primary">Convert to invoice</button><button wire:click="revise" class="btn-secondary">New revision</button>@elseif(in_array($quote->status,[\App\Enums\QuoteStatus::Rejected,\App\Enums\QuoteStatus::Expired]))<button wire:click="revise" class="btn-primary">New revision</button>@endif<a target="_blank" href="{{ route('finance.quotes.pdf',$quote) }}" class="btn-secondary">PDF</a></div></div><div class="grid gap-6 xl:grid-cols-[1.4fr_.6fr]"><section class="panel"><div class="panel-header"><div><h2>{{ $quote->subject }}</h2><p>Valid until {{ $quote->valid_until?->format('d M Y') }}</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Description</th><th>Quantity</th><th>Rate</th><th>Amount</th></tr></thead><tbody>@foreach($quote->lineItems as $line)<tr><td>{{ $line->description }}</td><td>{{ number_format((float)$line->quantity,2) }}</td><td>LKR {{ number_format((float)$line->rate,2) }}</td><td class="font-semibold">LKR {{ number_format((float)$line->amount,2) }}</td></tr>@endforeach</tbody><tfoot><tr><td colspan="3" class="px-5 py-4 text-right font-bold">Total</td><td class="px-5 py-4 text-lg font-bold">LKR {{ number_format($quote->totalAmount(),2) }}</td></tr></tfoot></table></div></section><aside class="space-y-6"><section class="panel p-5"><h2 class="font-bold">Revision history</h2><div class="mt-4 space-y-2">@foreach($quote->revisions as $revision)<a href="{{ route('admin.quotes.show',$revision) }}" class="flex justify-between rounded-lg p-2 text-sm hover:bg-slate-50 dark:hover:bg-slate-800"><span>Revision {{ $revision->revision }}</span><span>{{ $revision->status->label() }}</span></a>@endforeach</div></section><section class="panel p-5"><h2 class="font-bold">Audit trail</h2><div class="mt-4 space-y-3">@foreach($quote->actionLogs as $log)<div><p class="text-sm font-medium">{{ str_replace('_',' ',ucfirst($log->action)) }}</p><p class="text-xs text-slate-500">{{ $log->user?->name ?? 'System' }} · {{ $log->created_at->diffForHumans() }}</p></div>@endforeach</div></section></aside></div></div>
